
'use server';

import { createSupabaseServerClient } from '@/lib/supabase/server';
import { v4 as uuidv4 } from 'uuid';

// Helper to map FormData to a flat object for Supabase
const mapFormDataToDbObject = (formData: FormData): Record<string, any> => {
  const obj: Record<string, any> = {};
  for (const [key, value] of formData.entries()) {
    // Skip metadata fields that are handled separately
    if (['type', 'applicantName', 'userId'].includes(key)) continue;

    // Handle nested keys like 'identificationType.nationalIdCard'
    if (key.includes('.')) {
      const [parentKey, childKey] = key.split('.');
      const dbKey = `${parentKey}_${childKey}`.replace(/([A-Z])/g, '_$1').toLowerCase();
       obj[dbKey] = value === 'on' ? true : value;
    } else {
      // Convert camelCase to snake_case for DB columns
      const dbKey = key.replace(/([A-Z])/g, '_$1').toLowerCase();
       obj[dbKey] = value === 'on' ? true : value;
    }
  }
  return obj;
};

// NEW, DEDICATED ACTION FOR DIN GENERATION.
export async function generateDinAndSave(
    userId: string,
    applicantName: string,
    formData: FormData
): Promise<{ success: boolean; din?: string; error?: string; }> {
    
    const supabase = createSupabaseServerClient();
    const applicationData = mapFormDataToDbObject(formData);
    
    const submissionPayload = {
      ...applicationData,
      type: 'DIN Application',
      applicant_name: applicantName,
      user_id: userId,
      status: 'Approved', // DINs are auto-approved
    };

    try {
        const { data: insertedData, error: dbError } = await supabase
            .from('applications')
            .insert(submissionPayload)
            .select('id')
            .single();

        if (dbError || !insertedData) {
            throw dbError || new Error("Failed to insert application record.");
        }

        const newId = insertedData.id;
        const finalDin = `DIN${String(newId).padStart(3, '0')}`;
        
        const { error: updateError } = await supabase
            .from('applications')
            .update({ din: finalDin })
            .eq('id', newId);

        if (updateError) {
             console.error(`Failed to update application ${newId} with final DIN:`, updateError);
        }

        const { error: userUpdateError } = await supabase.auth.admin.updateUserById(
            userId,
            { user_metadata: { din: finalDin } }
        );
        if (userUpdateError) {
            console.error(`Failed to add DIN to user profile ${userId}:`, userUpdateError);
        }

        return { success: true, din: finalDin };

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'An unknown server error occurred.';
        console.error('DIN Generation Error:', errorMessage);
        return { success: false, error: `Failed to generate DIN: ${errorMessage}` };
    }
}

// This is the generic action for all OTHER form types.
export async function saveApplication(
    formData: FormData
): Promise<{ success: boolean; applicationId?: string; error?: string; }> {
    const supabase = createSupabaseServerClient();
    
    const type = formData.get('type') as string;
    const applicantName = formData.get('applicantName') as string;
    const userId = formData.get('userId') as string;

    if (!type || !applicantName || !userId) {
        return { success: false, error: 'Missing required application metadata.' };
    }

    if (type === 'DIN Application') {
        return { success: false, error: 'DIN Applications must use the dedicated generation service.' };
    }

    try {
        let submissionPayload: Record<string, any> = {
            type,
            applicant_name: applicantName,
            user_id: userId,
            status: 'Pending',
        };

        // Process all form fields, uploading files as they are found
        for (const [key, value] of formData.entries()) {
            if (['type', 'applicantName', 'userId'].includes(key)) continue;

            const dbKey = key.replace(/([A-Z])/g, '_$1').toLowerCase();

            if (value instanceof File && value.size > 0) {
                const filePath = `${userId}/${uuidv4()}-${value.name}`;
                const { error: uploadError } = await supabase.storage.from('application_documents').upload(filePath, value);
                if (uploadError) throw new Error(`Storage error for ${key}: ${uploadError.message}`);
                
                const { data: publicUrlData } = supabase.storage.from('application_documents').getPublicUrl(filePath);
                if (!publicUrlData.publicUrl) throw new Error(`Could not get public URL for ${key}.`);
                
                submissionPayload[`${dbKey}_url`] = publicUrlData.publicUrl; // Store URL in a dedicated column
            } else if (key.includes('.')) {
                // e.g., identificationType.nationalIdCard -> id_type_national_id_card
                const [parentKey, childKey] = key.split('.');
                const fullDbKey = `${parentKey.replace(/([A-Z])/g, '_$1').toLowerCase()}_${childKey.replace(/([A-Z])/g, '_$1').toLowerCase()}`;
                submissionPayload[fullDbKey] = value === 'on' ? true : value;
            } else if (value !== 'on' && !(value instanceof File)) {
                submissionPayload[dbKey] = value;
            } else if (value === 'on') {
                submissionPayload[dbKey] = true;
            }
        }
        
        const { data: insertedData, error: dbError } = await supabase
            .from('applications')
            .insert(submissionPayload)
            .select('id')
            .single();

        if (dbError || !insertedData) {
            throw dbError || new Error("Failed to insert application record.");
        }

        const finalApplicationId = `KSP${String(insertedData.id).padStart(3, '0')}`;
        
        const { error: appUpdateError } = await supabase
            .from('applications')
            .update({ original_permit_id: finalApplicationId }) // Using a real column now
            .eq('id', insertedData.id);

        if (appUpdateError) {
            console.error(`Failed to update application ${insertedData.id} with custom ID:`, appUpdateError);
        }

        return {
            success: true,
            applicationId: finalApplicationId,
        };

    } catch (error) {
        const errorMessage = error instanceof Error ? error.message : 'An unknown server error occurred.';
        console.error('Save Application Error:', errorMessage);
        return { success: false, error: `Failed to save application: ${errorMessage}` };
    }
}
